\begin{reference}
\cite[IV, Proposition 8.2.9]{EGA}
\end{reference}
Let $S = \lim S_i$ be the limit of a directed inverse system
of schemes with affine transition morphisms
(Lemma \ref{lemma-directed-inverse-system-has-limit}). Then
$S_{top} = \lim_i S_{i, top}$ where $S_{top}$
indicates the underlying topological space of the scheme $S$.

unconditional_or_other.statement:
Let $S$ be a scheme. Let $X$ and $Y$ be schemes over $S$.
Assume $Y$ is locally of finite presentation over $S$.
Let $x \in X$ be a closed point such that
$U = X \setminus \{x\} \to X$ is quasi-compact. With
$V = \Spec(\mathcal{O}_{X, x}) \setminus \{x\}$ there is
a bijection
$$
\left\{
\begin{matrix}
\text{morphisms }X \to Y\text{ over }S
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
(a, b)\text{ where }
a : U \to Y\text{ and }b : \Spec(\mathcal{O}_{X, x}) \to Y\\
\text{ are morphisms over }S
\text{ which agree over }V
\end{matrix}
\right\}
$$

Let $f : X \to S$ be a morphism of schemes.
Consider the diagrams
$$
\vcenter{
\xymatrix{
X_s \ar[r] \ar[d] & X \ar[d] \\
\Spec(\kappa(s)) \ar[r] & S
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
\Spec(\mathcal{O}_{S, s}) \times_S X \ar[r] \ar[d] & X \ar[d] \\
\Spec(\mathcal{O}_{S, s}) \ar[r] & S
}
}
$$
In both cases these diagrams induce fibre squares of topological
spaces and in particular, the top horizontal arrow is a homeomorphism
onto its image.

Let $S$ be a scheme. Let $s \in S$ be a closed point such that
$U = S \setminus \{s\} \to S$ is quasi-compact. With
$V = \Spec(\mathcal{O}_{S, s}) \setminus \{s\}$ the base change functor
$$
\left\{
\begin{matrix}
f : X \to S\text{ of finite presentation} \\
f^{-1}(U) \to U\text{ is an isomorphism}
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
g : Y \to \Spec(\mathcal{O}_{S, s})\text{ of finite presentation} \\
g^{-1}(V) \to V\text{ is an isomorphism}
\end{matrix}
\right\}
$$
is an equivalence of categories.

Let $S$ be a scheme. Let $U \subset S$ be a retrocompact open.
Let $s \in S$ be a point in the complement of $U$. With
$V = \Spec(\mathcal{O}_{S, s}) \cap U$ there is
an equivalence of categories
$$
\colim_{s \in U' \supset U\text{ open}}
\left\{
\vcenter{
\xymatrix{
X \ar[d] \\
U'
}
}
\right\}
\longrightarrow
\left\{
\vcenter{
\xymatrix{
X' \ar[d] & Y' \ar[d] \ar[l] \ar[r] & Y \ar[d] \\
U & V \ar[l] \ar[r] & \Spec(\mathcal{O}_{S, s})
}
}
\right\}
$$
where on the left hand side the vertical arrow is of finite
presentation and on the right hand side we consider commutative diagrams
whose squares are cartesian and whose vertical arrows are
of finite presentation.

citation_as_in.statement:
\begin{reference}
This is a special case of \cite[Satz 2]{Faltings-finiteness}.
\end{reference}
Let $A$ be a Noetherian ring and let $I \subset A$ be an ideal.
Set $Z = V(I) \subset \Spec(A)$. Let $M$ be a finite $A$-module.
Set $s = s_{A, I}(M)$ as in (\ref{equation-cutoff}).
Assume that
\begin{enumerate}
\item $A$ is universally catenary,
\item the formal fibres of the local rings of $A$ are Cohen-Macaulay.
\end{enumerate}
Then $H^i_Z(M)$ is finite for $0 \leq i < s$ and
$H^s_Z(M)$ is not finite.

dependent_construction.statement:
Let $S$ be a scheme. Let $X \to Z \to B$ be morphisms of
algebraic spaces over $S$. The following diagram
$$
\xymatrix{
\mathit{Mor}_B(Z, X) \ar[r] & \mathit{Mor}_B(Z, Z) \\
\text{Res}_{Z/B}(X) \ar[r] \ar[u] & B \ar[u]_{\text{id}_Z}
}
$$
is a cartesian diagram of sheaves on $(\Sch/S)_{fppf}$.

Let $S$ be a scheme. Let $f : X \to Y$ and $h : U \to X$ be morphisms of
algebraic spaces over $S$. If
\begin{enumerate}
\item $f$ and $h$ are quasi-compact,
\item $|h|(|U|)$ is dense in $|X|$, and
\end{enumerate}
given any commutative solid diagram
$$
\xymatrix{
\Spec(K) \ar[r] \ar[d] & U \ar[r] & X \ar[d] \\
\Spec(A) \ar[rr] \ar@{-->}[rru] & & Y
}
$$
where $A$ is a valuation ring with field of fractions $K$
\begin{enumerate}
\item[(3)] there exists at most one dotted arrow making the diagram
commute, and
\item[(4)] there exists an extension $K'/K$ of fields, a
valuation ring $A' \subset K'$ dominating $A$ and a morphism
$\Spec(A') \to X$ such that the following diagram commutes
$$
\xymatrix{
\Spec(K') \ar[r] \ar[d] & \Spec(K) \ar[r] & U \ar[r] & X \ar[d] \\
\Spec(A') \ar[r] \ar[rrru] & \Spec(A) \ar[rr] & & Y
}
$$
\end{enumerate}
then $f$ is universally closed. If moreover
\begin{enumerate}
\item[(5)] $f$ is quasi-separated
\end{enumerate}
then $f$ is separated and universally closed.

notation_or_hypotheses.statement:
With notation as in
Lemma \ref{lemma-enough-injectives}
we have $R^pQ(F) = 0$ for all $p > 0$ and any adequate functor $F$.

With notation as in More on Morphisms, Lemma \ref{more-morphisms-lemma-blowup}
for $a \geq 0$ we have
\begin{enumerate}
\item the map
$\Omega^a_{X/S} \to b_*\Omega^a_{X'/S}$ is an isomorphism,
\item the map $\Omega^a_{Z/S} \to p_*\Omega^a_{E/S}$ is an isomorphism,
\item the map $Rb_*\Omega^a_{X'/S} \to i_*Rp_*\Omega^a_{E/S}$ is an isomorphism
on cohomology sheaves in degree $\geq 1$.
\end{enumerate}

With notation as in (\ref{equation-three-maps}) set
$$
\begin{matrix}
\Omega_1 = \Omega_{\mathcal{O}/A} \otimes_\mathcal{O} \underline{B}
\text{ on }\mathcal{C}_{B/A} \\
\Omega_2 = \Omega_{\mathcal{O}/A} \otimes_\mathcal{O} \underline{C}
\text{ on }\mathcal{C}_{C/A} \\
\Omega_3 = \Omega_{\mathcal{O}/B} \otimes_\mathcal{O} \underline{C}
\text{ on }\mathcal{C}_{C/B}
\end{matrix}
$$
Then we have a canonical short exact sequence of sheaves
of $\underline{C}$-modules
$$
0 \to g_1^{-1}\Omega_1 \otimes_{\underline{B}} \underline{C} \to
g_2^{-1}\Omega_2 \to
g_3^{-1}\Omega_3 \to 0
$$
on $\mathcal{C}_{C/B/A}$.

With notation as in More on Morphisms, Lemma \ref{more-morphisms-lemma-blowup}
the map $\Omega^\bullet_{X/S} \to Rb_*\Omega^\bullet_{X'/S}$
has a splitting in $D(X, (X \to S)^{-1}\mathcal{O}_S)$.

reference_to_prior.statement:
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
Let $x \in |\mathcal{X}|$. Consider commutative diagrams
$$
\vcenter{
\xymatrix{
U \ar[d]_a \ar[r]_h & V \ar[d]^b \\
\mathcal{X} \ar[r]^f & \mathcal{Y}
}
}
\quad\text{with points}
\vcenter{
\xymatrix{
u \in |U| \ar[d] \\
x \in |\mathcal{X}|
}
}
$$
where $U$ and $V$ are algebraic spaces, $b$ is flat, and
$(a, h) : U \to \mathcal{X} \times_\mathcal{Y} V$
is flat. The following are equivalent
\begin{enumerate}
\item $h$ is flat at $u$ for one diagram as above,
\item $h$ is flat at $u$ for every diagram as above.
\end{enumerate}

source_reference_prefix.statement:
\begin{reference}
\cite[Theorem I]{Taussky}
\end{reference}
Let $A = (a_{ij})$ be a complex $n \times n$ matrix.
\begin{enumerate}
\item If $|a_{ii}| > \sum_{j \not = i} |a_{ij}|$ for each $i$, then
$\det(A)$ is nonzero.
\item If there exists a real vector $m = (m_1, \ldots, m_n)$
with $m_i > 0$ such that $|a_{ii} m_i| > \sum_{j \not = i} |a_{ij}m_j|$
for each $i$, then $\det(A)$ is nonzero.
\end{enumerate}

\begin{reference}
\cite[Section 6.8]{EGA1-second}
\end{reference}
Let $X$ be a scheme. Let $\mathcal{L}$ be an invertible sheaf on $X$.
Let $s \in \Gamma(X, \mathcal{L})$. Let $\mathcal{F}$ be a quasi-coherent
$\mathcal{O}_X$-module.
\begin{enumerate}
\item If $X$ is quasi-compact, then (\ref{equation-module-invert-s})
is injective, and
\item if $X$ is quasi-compact and quasi-separated, then
(\ref{equation-module-invert-s}) is an isomorphism.
\end{enumerate}
In particular, the canonical map
$$
\Gamma_*(X, \mathcal{L})_{(s)}
\longrightarrow
\Gamma(X_s, \mathcal{O}_X),\quad
a/s^n \longmapsto a \otimes s^{-n}
$$
is an isomorphism if $X$ is quasi-compact and quasi-separated.

\begin{reference}
Special case of \cite[Proposition 1.3]{totaro_resolution}.
\end{reference}
Let $X$ be a quasi-compact and quasi-separated scheme with
the resolution property. Then $X$ has affine diagonal.

\begin{reference}
\cite[III Theorem 3.2.1]{EGA}
\end{reference}
Let $S$ be a locally Noetherian scheme.
Let $f : X \to S$ be a proper morphism.
Let $\mathcal{F}$ be a coherent $\mathcal{O}_X$-module.
Then $R^if_*\mathcal{F}$ is a coherent $\mathcal{O}_S$-module
for all $i \geq 0$.

\begin{reference}
\cite[Proposition 7.5.5]{EGA1}
\end{reference}
Let $A$ be a Noetherian ring and let $I \subset A$ be an ideal. Then
\begin{enumerate}
\item every object of the category $\mathcal{C}'$
(\ref{equation-C-prime}) is Noetherian,
\item if $B \in \Ob(\mathcal{C}')$ and $J \subset B$ is an ideal,
then $B/J$ is an object of $\mathcal{C}'$,
\item for a finite type $A$-algebra $C$ the $I$-adic completion
$C^\wedge$ is in $\mathcal{C}'$,
\item in particular the completion $A[x_1, \ldots, x_r]^\wedge$
is in $\mathcal{C}'$.
\end{enumerate}

\begin{reference}
\cite[Proposition 2.1]{Hartshorne-connectedness}
\end{reference}

Let $A$ be a Noetherian local ring of depth $\geq 2$.
Then the punctured spectra of $A$, $A^h$, and $A^{sh}$ are connected.

\begin{reference}
Our proof follows closely the proof given in \cite[Theorem 1.2.2]{CLO}.
\end{reference}
Let $X$ be a quasi-compact and quasi-separated algebraic space over
$\Spec(\mathbf{Z})$. There exist a directed set $I$
and an inverse system of algebraic spaces $(X_i, f_{ii'})$ over $I$
such that
\begin{enumerate}
\item the transition morphisms $f_{ii'}$ are affine
\item each $X_i$ is quasi-separated and of finite type over
$\mathbf{Z}$, and
\item $X = \lim X_i$.
\end{enumerate}

